INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank, toeic_rank) VALUES
(2200, 'outstanding', '/aʊtˈstændɪŋ/', 'adjective', '{"zh-TW":["傑出的","未解決的"],"en":["excellent","not yet resolved"]}', '{"prefix":{"text":"out-","meaning":"超出"},"root":{"text":"standing","meaning":"站立"}}', 'outstanding performance / outstanding balance', '[{"en":"She received an award for outstanding performance.","zh-TW":"她因傑出表現獲獎。"},{"en":"There are outstanding invoices.","zh-TW":"有未付的發票。"}]', '{"adverb":"outstandingly"}', NULL, 4, 2200, 168),
(2201, 'over', '/ˈoʊvər/', 'adjective, adverb, preposition', '{"zh-TW":["【主要意義-介系詞/副詞】在……上面；超過","【次要意義-形容詞】結束的；完了的","【次要意義-副詞】重新；再次（over again）","【次要意義-副詞】剩餘的；多出的"],"en":["[primary] above; more than; across","[secondary - adjective] finished or ended","[secondary - adverb] once again; repeatedly","[secondary - adverb] remaining after something has been used"]}', NULL, 'it is over / over and above / over and over / left over / once it is over', '[{"en":"Once the fiscal year is over, we will review the budget allocation.","zh-TW":"財政年度結束後，我們將審查預算分配。"},{"en":"Employees were asked to review the policy over and over to ensure compliance.","zh-TW":"員工被要求反覆審查政策以確保合規。"},{"en":"Any funds left over after the project will be returned to the reserve fund.","zh-TW":"專案結束後剩餘的任何資金將歸還給準備金。"}]', '{"noun":"overtime, overhaul","adjective":"overall"}', 'over 作形容詞表「結束的」（it is all over），leftover（剩餘的）、over and above（超出此外）、overall（整體的）均是 TOEIC 商業文章的高頻詞彙。', 1, 2201, NULL),
(2202, 'overall', '/ˌoʊvərˈɔːl/', 'adjective', '{"zh-TW":["整體的；全面的"],"en":["including everything; total"]}', '{"prefix":{"text":"over-","meaning":"全部"},"root":{"text":"all","meaning":"所有"}}', 'overall performance / overall cost', '[{"en":"The overall cost exceeded the budget.","zh-TW":"總成本超出預算。"},{"en":"Overall, results were satisfactory.","zh-TW":"總體而言結果令人滿意。"}]', '{"adverb":"overall"}', NULL, 3, 2202, NULL),
(2203, 'overbooking', '/ˌəʊvəˈbʊkɪŋ/', 'noun', '{"zh-TW":["超額預訂"],"en":["the practice of selling more seats than are available"]}', NULL, 'airline overbooking / overbooking policy', '[{"en":"The airline compensated passengers due to overbooking.","zh-TW":"航空公司因超額預訂而賠償乘客。"},{"en":"Overbooking can result in denied boarding for some passengers.","zh-TW":"超額預訂可能導致部分乘客被拒絕登機。"}]', '{"verb":"overbook","adjective":"overbooked"}', NULL, 4, 2203, NULL),
(2204, 'overcome', '/ˌoʊvərˈkʌm/', 'verb', '{"zh-TW":["克服","克服；戰勝"],"en":["to succeed in dealing with a problem","to succeed in dealing with difficulty"]}', '{"prefix":{"text":"over-","meaning":"over (越過)"},"root":{"text":"come","meaning":"come (到來)"},"logic":"越過困難而到達，即「克服」。"}', 'overcome obstacles / overcome challenges / overcome fear; overcome difficulties / overcome obstacles', '[{"en":"She overcame many obstacles to succeed.","zh-TW":"她克服了許多障礙才成功。"},{"en":"He is trying to overcome his fear of public speaking.","zh-TW":"他正在試圖克服對公開演講的恐懼。"},{"en":"She overcame many challenges.","zh-TW":"她克服了許多挑戰。"},{"en":"We must overcome these difficulties.","zh-TW":"我們必須克服這些困難。"}]', NULL, NULL, 3, 2204, 704),
(2205, 'overdraft', '/ˈəʊvədrɑːft/', 'noun', '{"zh-TW":["透支；超支"],"en":["a facility allowing spending beyond available bank balance"]}', NULL, 'go into overdraft / overdraft protection', '[{"en":"He accidentally went into overdraft and was charged a fee.","zh-TW":"他不小心透支並被收取了費用。"},{"en":"Overdraft protection prevents transactions from being declined.","zh-TW":"透支保護可防止交易被拒絕。"}]', '{"verb":"overdraw","adjective":"overdrawn"}', NULL, 3, 2205, NULL),
(2206, 'overdue', '/ˌəʊvəˈdjuː/', 'adjective', '{"zh-TW":["逾期的；過期的"],"en":["past the time when it was expected or required"]}', NULL, 'overdue invoice / overdue payment', '[{"en":"The invoice is now 30 days overdue.","zh-TW":"發票現在已逾期30天。"},{"en":"Please settle the overdue balance immediately.","zh-TW":"請立即結清逾期餘額。"}]', NULL, NULL, 3, 2206, NULL),
(2207, 'overhaul', '/ˈoʊvərhɔːl/', 'noun', '{"zh-TW":["徹底檢修；大改革"],"en":["a thorough examination and repair or revision of something"]}', NULL, 'system overhaul / policy overhaul / complete overhaul', '[{"en":"The IT system underwent a complete overhaul to improve performance.","zh-TW":"IT系統進行了全面翻修以提高性能。"},{"en":"A policy overhaul was announced to align with new regulations.","zh-TW":"宣佈進行政策大改革以符合新法規。"}]', '{"verb":"overhaul","adjective":"overhauled"}', NULL, 3, 2207, NULL),
(2208, 'overhead', '/ˈoʊvərˌhɛd/', 'noun', '{"zh-TW":["管理費用；經常性開支"],"en":["ongoing business expenses not directly tied to production"]}', NULL, 'overhead costs / reduce overhead', '[{"en":"We need to reduce overhead costs.","zh-TW":"我們需要降低管理費用。"},{"en":"Rent is our biggest overhead expense.","zh-TW":"租金是我們最大的經常性開支。"}]', '{"noun":"overhead","adjective":"overhead"}', NULL, 3, 2208, 406),
(2209, 'overheads', '/ˈoʊvərhedz/', 'noun', '{"zh-TW":["間接費用；管理費用"],"en":["the general costs of running a business not tied to specific products"]}', NULL, 'reduce overheads / fixed overheads / high overheads', '[{"en":"Reducing overheads by moving to a smaller office saved 200000 annually.","zh-TW":"通過搬至更小的辦公室降低間接費用每年節省了20萬元。"},{"en":"Overheads include utilities, rent, and administrative salaries.","zh-TW":"間接費用包括水電費、租金和行政薪資。"}]', NULL, NULL, 3, 2209, NULL),
(2210, 'overlook', '/ˌoʊvərˈlʊk/', 'verb', '{"zh-TW":["忽略","俯瞰"],"en":["to fail to notice","to have a view over"]}', '{"prefix":{"text":"over-","meaning":"over"},"root":{"text":"look","meaning":"看"}}', 'overlook a detail / easily overlooked', '[{"en":"Don''t overlook the fine print.","zh-TW":"別忽略小字。"},{"en":"This detail was overlooked.","zh-TW":"這個細節被忽視了。"}]', NULL, NULL, 3, 2210, NULL),
(2211, 'override', '/ˌoʊvərˈraɪd/', 'verb', '{"zh-TW":["推翻；凌駕"],"en":["to use authority to cancel or reverse a decision made by someone else"]}', NULL, 'override a decision / override a system / override authority', '[{"en":"The senior manager overrode the department head''s approval.","zh-TW":"高級經理推翻了部門主管的批准決定。"},{"en":"An administrator can override default system settings.","zh-TW":"管理員可以覆蓋系統默認設置。"}]', '{"noun":"override"}', NULL, 3, 2211, NULL),
(2212, 'overrun', '/ˈoʊvərʌn/', 'noun', '{"zh-TW":["超支；超時"],"en":["an amount by which costs or time exceed the planned budget or schedule"]}', NULL, 'budget overrun / time overrun', '[{"en":"The construction project experienced a 15% cost overrun.","zh-TW":"建設項目出現了15%的成本超支。"},{"en":"Overruns on major projects require board approval for additional funding.","zh-TW":"主要項目的超支需要董事會批准額外資金。"}]', '{"verb":"overrun"}', NULL, 3, 2212, NULL),
(2213, 'overseas', '/ˌoʊvərˈsiːz/', 'adverb', '{"zh-TW":["海外的"],"en":["in a foreign country"]}', '{"prefix":{"text":"over-","meaning":"越過"},"root":{"text":"seas","meaning":"海洋"}}', 'overseas market / go overseas', '[{"en":"The company is expanding overseas.","zh-TW":"公司正在海外擴展。"},{"en":"Many graduates seek employment overseas.","zh-TW":"許多畢業生在海外求職。"}]', NULL, NULL, 3, 2213, NULL),
(2214, 'oversee', '/ˌəʊvəˈsiː/', 'verb', '{"zh-TW":["監督；管理"],"en":["to watch over and direct an activity or process"]}', NULL, 'oversee operations / oversee a project', '[{"en":"He was appointed to oversee the construction project.","zh-TW":"他被任命監督建設項目。"},{"en":"The manager oversees a team of twenty employees.","zh-TW":"經理監督一個由二十名員工組成的團隊。"}]', '{"noun":"oversight","noun2":"overseer","adjective":"overseen"}', NULL, 3, 2214, 407),
(2215, 'oversight', '/ˈoʊvərsaɪt/', 'noun', '{"zh-TW":["監督；疏忽"],"en":["supervision and control of a process or organization; also an accidental omission"]}', NULL, 'provide oversight / regulatory oversight / management oversight', '[{"en":"The board has oversight responsibility for the risk management framework.","zh-TW":"董事會對風險管理框架負有監督責任。"},{"en":"The error was due to an oversight in the review process.","zh-TW":"這個錯誤是由於審查過程中的疏忽造成的。"}]', '{"verb":"oversee","adjective":"overseen"}', NULL, 3, 2215, 899),
(2216, 'overstock', '/ˈoʊvərstɒk/', 'noun', '{"zh-TW":["過剩庫存；超額庫存"],"en":["having more inventory than is needed to meet current demand"]}', NULL, 'deal with overstock / reduce overstock', '[{"en":"Overstocking ties up capital and increases storage costs.","zh-TW":"過剩庫存佔用資本並增加倉儲成本。"},{"en":"The retailer discounted items to clear overstock before the season ended.","zh-TW":"零售商在季節結束前打折清理過剩庫存。"}]', '{"verb":"overstock","adjective":"overstocked"}', NULL, 3, 2216, NULL),
(2217, 'overtime', '/ˈoʊvərtaɪm/', 'noun', '{"zh-TW":["加班"],"en":["time worked beyond normal hours"]}', '{"prefix":{"text":"over-","meaning":"超過"},"root":{"text":"time","meaning":"時間"}}', 'work overtime / overtime pay', '[{"en":"Employees are paid extra for overtime.","zh-TW":"員工加班有額外報酬。"},{"en":"She works overtime to meet deadlines.","zh-TW":"她加班趕截止日期。"}]', NULL, NULL, 3, 2217, NULL),
(2218, 'overvalue', '/ˌoʊvərˈvæljuː/', 'verb', '{"zh-TW":["高估；定價過高"],"en":["to place too high a value on something"]}', NULL, 'overvalue an asset / stock is overvalued', '[{"en":"Analysts warned the stock was overvalued at current prices.","zh-TW":"分析師警告股票在當前價格下被高估了。"},{"en":"An overvalued currency makes exports less competitive.","zh-TW":"高估的貨幣使出口競爭力下降。"}]', '{"noun":"overvaluation","adjective":"overvalued"}', NULL, 3, 2218, NULL),
(2219, 'overview', '/ˈoʊvərvjuː/', 'noun', '{"zh-TW":["概述；總覽"],"en":["a general summary"]}', '{"prefix":{"text":"over-","meaning":"全面"},"root":{"text":"view","meaning":"看"}}', 'brief overview / overview of the project', '[{"en":"The report provides an overview of trends.","zh-TW":"報告提供了趨勢概述。"},{"en":"Let me give a brief overview.","zh-TW":"讓我簡要概述。"}]', NULL, NULL, 3, 2219, 169),
(2220, 'overwhelm', '/ˌoʊvərˈwɛlm/', 'verb', '{"zh-TW":["壓倒；使不知所措"],"en":["to be too much to deal with"]}', '{"prefix":{"text":"over-","meaning":"過度"},"root":{"text":"whelm","meaning":"submerge (淹沒)"}}', 'be overwhelmed by / overwhelming majority', '[{"en":"She was overwhelmed by the workload.","zh-TW":"她被工作量壓垮了。"},{"en":"The response was overwhelming.","zh-TW":"反應非常熱烈。"}]', '{"adjective":"overwhelming, overwhelmed","adverb":"overwhelmingly"}', NULL, 3, 2220, NULL),
(2221, 'owe', '/oʊ/', 'verb', '{"zh-TW":["欠","歸功於"],"en":["to need to pay back","to have because of help"]}', NULL, 'owe money / owe sb. a favor', '[{"en":"The company owes $5 million.","zh-TW":"公司欠五百萬美元。"},{"en":"I owe my success to my mentor.","zh-TW":"我的成功歸功於導師。"}]', NULL, NULL, 1, 2221, NULL),
(2222, 'owner-operator', '/ˈoʊnər ˈɒpəreɪtər/', 'noun', '{"zh-TW":["業主兼經營者"],"en":["a person who both owns and runs a business"]}', NULL, 'independent owner-operator / owner-operator model', '[{"en":"The franchise is run by an owner-operator with 10 years experience.","zh-TW":"特許經營由一名擁有10年經驗的業主兼經營者管理。"},{"en":"Owner-operators are strongly motivated to succeed.","zh-TW":"業主兼經營者有強烈的成功動機。"}]', NULL, NULL, 5, 2222, NULL),
(2223, 'ownership', '/ˈəʊnərʃɪp/', 'noun', '{"zh-TW":["所有權；擁有"],"en":["the fact of owning something"]}', NULL, 'transfer of ownership / sole ownership', '[{"en":"The transfer of ownership was completed last month.","zh-TW":"所有權轉讓上個月完成了。"},{"en":"She took ownership of the project and delivered excellent results.","zh-TW":"她承擔了項目的責任並交出了出色的成果。"}]', '{"verb":"own","noun":"owner","adjective":"owned"}', NULL, 3, 2223, NULL),
(2224, 'pace', '/peɪs/', 'noun', '{"zh-TW":["步伐；速度"],"en":["the speed of movement or activity"]}', NULL, 'at a fast pace / keep pace with / set the pace', '[{"en":"The pace of technological change is rapid.","zh-TW":"技術變革的步伐很快。"},{"en":"We need to keep pace with competitors.","zh-TW":"我們需要跟上競爭對手。"}]', '{"verb":"pace"}', NULL, 1, 2224, NULL),
(2225, 'package', '/ˈpækɪdʒ/', 'noun', '{"zh-TW":["包裹","套裝；方案"],"en":["a wrapped object","a set of things offered together"]}', NULL, 'compensation package / package deal', '[{"en":"The package was delivered this morning.","zh-TW":"包裹今早送達了。"},{"en":"They offered an attractive compensation package.","zh-TW":"他們提供了優厚的薪酬方案。"}]', '{"verb":"package","noun":"packaging"}', NULL, 3, 2225, 408),
(2226, 'packaging', '/ˈpækɪdʒɪŋ/', 'noun', '{"zh-TW":["包裝"],"en":["materials used to wrap or protect goods"]}', '{"root":{"text":"pack","meaning":"bundle (打包)"},"suffix":{"text":"-aging","meaning":"process of (過程)"},"logic":"打包的過程或材料，即「包裝」。"}', 'eco-friendly packaging / product packaging', '[{"en":"The packaging was damaged during shipping.","zh-TW":"包裝在運送過程中受損。"},{"en":"We use eco-friendly packaging materials.","zh-TW":"我們使用環保包裝材料。"}]', '{"verb":"package","noun":"package"}', NULL, 3, 2226, NULL),
(2227, 'page', '/peɪdʒ/', 'noun', '{"zh-TW":["頁面；網頁"],"en":["one side of a sheet of paper","a section of a website"]}', NULL, 'home page / on the same page', '[{"en":"Let''s make sure we are on the same page.","zh-TW":"讓我們確認彼此有共識。"},{"en":"Visit our web page for more details.","zh-TW":"請瀏覽我們的網頁了解更多。"}]', '{"noun":"page","noun2":"webpage"}', NULL, 1, 2227, NULL),
(2228, 'pain', '/peɪn/', 'noun', '{"zh-TW":["痛苦；疼痛"],"en":["physical suffering","mental distress"]}', NULL, 'pain point / no pain no gain', '[{"en":"We identified the customer''s pain points.","zh-TW":"我們找出了客戶的痛點。"},{"en":"No pain, no gain in business.","zh-TW":"商場上不吃苦就沒有收穫。"}]', '{"noun":"pain","adjective":"painful","adjective2":"painless","adverb":"painfully"}', NULL, 1, 2228, NULL),
(2229, 'paint', '/peɪnt/', 'verb', '{"zh-TW":["油漆；繪畫"],"en":["to apply color to a surface","to create a picture"]}', NULL, 'paint a picture / fresh paint', '[{"en":"Let me paint a picture of our vision.","zh-TW":"讓我描繪我們的願景。"},{"en":"The office walls need fresh paint.","zh-TW":"辦公室牆壁需要重新粉刷。"}]', '{"verb":"paint","noun":"paint","noun2":"painter","noun3":"painting"}', NULL, 2, 2229, NULL),
(2230, 'palette', '/ˈpælɪt/', 'noun', '{"zh-TW":["調色盤；色彩範圍"],"en":["a board for mixing paints","a range of colors used"]}', '{"root":{"text":"palette","meaning":"small blade (小板子)"},"logic":"源自法語，指畫家用來混合顏料的小板子。"}', 'color palette / artist''s palette', '[{"en":"The artist mixed colors on her palette.","zh-TW":"藝術家在調色盤上混合顏色。"},{"en":"The designer chose a warm color palette.","zh-TW":"設計師選擇了暖色調色盤。"}]', NULL, NULL, 3, 2230, NULL),
(2231, 'panel', '/ˈpænəl/', 'noun', '{"zh-TW":["專家小組","面板"],"en":["a group of experts","a flat surface"]}', NULL, 'panel discussion / solar panel / panel of judges', '[{"en":"A panel of experts discussed the issue.","zh-TW":"一組專家討論了這問題。"},{"en":"The company installed solar panels.","zh-TW":"公司安裝了太陽能板。"}]', '{"noun":"panelist"}', NULL, 2, 2231, NULL),
(2232, 'paper', '/ˈpeɪpər/', 'noun', '{"zh-TW":["【主要意義-名詞】紙；報紙","【次要意義-形容詞】表面上的；名義上的；紙面上的","【次要意義-名詞】學術論文；政策文件"],"en":["[primary - noun] thin material used for writing or printing","[secondary - adjective] existing only in theory; not having real substance","[secondary - noun] an academic article or a policy document"]}', NULL, 'paper profit / paper qualifications / on paper / position paper / white paper', '[{"en":"The merger looked great on paper but failed in practice.","zh-TW":"這次合併在紙面上看起來很好，但實際上卻失敗了。"},{"en":"The company reported paper profits due to asset revaluation.","zh-TW":"由於資產重估，公司報告了帳面利潤。"},{"en":"She presented a research paper on consumer behavior at the conference.","zh-TW":"她在會議上發表了一篇關於消費者行為的研究論文。"}]', '{"verb":"paper over","noun":"paperwork"}', 'paper 作形容詞意為「名義上的/帳面上的」（如 paper profit = 帳面利潤），on paper = 理論上，這些是 TOEIC 財務或商業文章的常見陷阱表達。', 2, 2232, NULL),
(2233, 'paperwork', '/ˈpeɪpərwɜːrk/', 'noun', '{"zh-TW":["文書工作；書面工作"],"en":["routine work involving completing and handling documents"]}', NULL, 'complete paperwork / reduce paperwork', '[{"en":"Please complete all required paperwork before your first day.","zh-TW":"請在您上班的第一天前完成所有必要的文書工作。"},{"en":"Digital systems have helped reduce time spent on paperwork.","zh-TW":"數位系統幫助減少了在文書工作上花費的時間。"}]', NULL, NULL, 3, 2233, NULL),
(2234, 'paradigm', '/ˈpærədaɪm/', 'noun', '{"zh-TW":["典範；範式"],"en":["a typical example or model","a framework of thinking"]}', NULL, 'paradigm shift / new paradigm', '[{"en":"AI represents a paradigm shift in business.","zh-TW":"AI代表著商業的典範轉移。"},{"en":"We need a new paradigm for customer service.","zh-TW":"我們需要客戶服務的新典範。"}]', '{"noun":"paradigm","adjective":"paradigmatic"}', NULL, 3, 2234, NULL),
(2235, 'parallel', '/ˈpærəlɛl/', 'adjective', '{"zh-TW":["平行的","類似的"],"en":["extending in the same direction","similar"]}', '{"root":{"text":"para","meaning":"beside (旁邊)"},"suffix":{"text":"llel","meaning":"each other"}}', 'parallel to / run parallel / draw a parallel', '[{"en":"The two roads run parallel to each other.","zh-TW":"兩條路平行延伸。"},{"en":"There are parallels between the two cases.","zh-TW":"兩個案例有相似之處。"}]', '{"noun":"parallel","adverb":"parallelly"}', NULL, 3, 2235, NULL),
(2236, 'parameter', '/pəˈræmɪtər/', 'noun', '{"zh-TW":["參數；範圍"],"en":["a limit or boundary; a variable"]}', '{"root":{"text":"para","meaning":"beside"},"suffix":{"text":"meter","meaning":"measure (量)"}}', 'within the parameters / set parameters', '[{"en":"We must work within the parameters of the budget.","zh-TW":"我們必須在預算範圍內工作。"},{"en":"The manager set clear parameters for the project.","zh-TW":"經理為項目設定了明確的參數。"}]', NULL, NULL, 3, 2236, NULL),
(2237, 'parent', '/ˈpɛrənt/', 'noun', '{"zh-TW":["父母；母公司"],"en":["a mother or father","a company that owns another"]}', NULL, 'parent company / single parent', '[{"en":"The parent company is in Japan.","zh-TW":"母公司在日本。"},{"en":"Many employees are working parents.","zh-TW":"許多員工是在職父母。"}]', '{"noun":"parent","adjective":"parental","noun2":"parenthood"}', NULL, 2, 2237, NULL),
(2238, 'parity', '/ˈpærɪti/', 'noun', '{"zh-TW":["平價；同等"],"en":["the state of being equal in status, value, or level"]}', NULL, 'achieve parity / parity with competitors', '[{"en":"The new pay scale brought salaries to parity with industry peers.","zh-TW":"新薪酬制度使薪資與同行業持平。"},{"en":"Currency parity means two currencies have the same exchange value.","zh-TW":"貨幣平價意味著兩種貨幣具有相同的匯率價值。"}]', '{"adjective":"at parity","opposite":"disparity"}', NULL, 2, 2238, NULL),
(2239, 'park', '/pɑːrk/', 'noun', '{"zh-TW":["公園；停車"],"en":["a public area for recreation","to leave a vehicle"]}', NULL, 'car park / industrial park', '[{"en":"The factory is in the industrial park.","zh-TW":"工廠在工業園區內。"},{"en":"Where can I park my car?","zh-TW":"我可以在哪裡停車？"}]', '{"noun":"park","verb":"park","noun2":"parking"}', NULL, 1, 2239, NULL),
(2240, 'parole', '/pəˈroʊl/', 'noun', '{"zh-TW":["假釋"],"en":["early release from prison with conditions"]}', NULL, 'on parole / parole board', '[{"en":"He was released on parole.","zh-TW":"他被假釋出獄。"},{"en":"The parole board denied his request.","zh-TW":"假釋委員會拒絕了他的請求。"}]', NULL, NULL, 2, 2240, NULL),
(2241, 'part', 'pɑːrt', 'noun', '{"zh-TW":["部分；零件","角色"],"en":["a piece of something larger","a role in something"]}', NULL, 'spare part/take part', '[{"en":"Each part of the plan is important.","zh-TW":"計畫的每個部分都很重要。"}]', '{"verb":"participate","adjective":"partial","adverb":"partially"}', NULL, 1, 2241, NULL),
(2242, 'participate', '/pɑːrˈtɪsɪpeɪt/', 'verb', '{"zh-TW":["參與","參加；參與"],"en":["to take part in an activity"]}', '{"root":{"text":"part","meaning":"part (部分)"},"suffix":{"text":"-icipate","meaning":"take (取得)"},"logic":"取得一份參與，即「參與」。"}', 'participate in / active participant; participate in / active participation', '[{"en":"Everyone is encouraged to participate in the discussion.","zh-TW":"鼓勵每個人參與討論。"},{"en":"Over 500 people participated in the survey.","zh-TW":"超過500人參與了調查。"},{"en":"All employees are encouraged to participate.","zh-TW":"鼓勵所有員工參與。"},{"en":"She participated in the training program.","zh-TW":"她參加了培訓計劃。"}]', '{"noun":"participation","noun2":"participant","adjective":"participatory"}', NULL, 4, 2242, 170),
(2243, 'participation', 'pɑːrˌtɪsɪˈpeɪʃən', 'noun', '{"zh-TW":["參與；參加","加入"],"en":["the act of taking part","involvement"]}', NULL, 'encourage participation/active participation', '[{"en":"Active participation is encouraged.","zh-TW":"鼓勵積極參與。"}]', '{"verb":"participate","adjective":"participating"}', NULL, 5, 2243, 602),
