(2245, 'partner', 'ˈpɑːrtnər', 'verb', '{"zh-TW":["合作；合夥","配對"],"en":["to work together with","to form a partnership"]}', NULL, 'partner with/partner on a project', '[{"en":"We partnered with a local supplier.","zh-TW":"我們與本地供應商合作。"}]', '{"noun":"partner, partnership","adjective":"partnered"}', NULL, 3, 2245, 410),
(2246, 'partnership', '/ˈpɑːrtnərʃɪp/', 'noun', '{"zh-TW":["合夥；夥伴關係"],"en":["a relationship between partners"]}', '{"root":{"text":"partner","meaning":"夥伴"},"suffix":{"text":"-ship","meaning":"狀態"}}', 'form a partnership / business partnership / in partnership with', '[{"en":"The two companies formed a strategic partnership.","zh-TW":"兩家公司建立了策略夥伴關係。"},{"en":"We work in partnership with local suppliers.","zh-TW":"我們與當地供應商合作。"}]', '{"noun":"partner"}', NULL, 4, 2246, NULL),
(2247, 'party', '/ˈpɑːrti/', 'noun', '{"zh-TW":["【主要意義-名詞】派對；聚會；政黨","【次要意義-名詞（法律）】當事人；一方（合約或訴訟中）","【次要意義-動詞】參與；加入"],"en":["[primary - noun] a social gathering; a political organization","[secondary - noun] a person or group involved in a legal agreement or dispute","[secondary - verb] to attend or take part in parties or celebrations"]}', NULL, 'third party / the contracting parties / party to an agreement / party involved', '[{"en":"Both parties must sign the agreement before it takes effect.","zh-TW":"雙方必須在協議生效之前簽署。"},{"en":"A third-party inspection is required before the goods are shipped.","zh-TW":"貨物出貨前需要第三方檢驗。"},{"en":"Please ensure all parties involved are notified of the schedule change.","zh-TW":"請確保所有相關方都被通知到時間表的變更。"}]', '{"adjective":"bipartisan"}', 'party 在法律和商業語境中意為「當事人/一方」，third party（第三方）、contracting parties（締約方）是 TOEIC 合約類文章必考詞彙，考生常誤以為只有「派對」的意思。', 2, 2247, NULL),
(2248, 'pass', '/pæs/', 'verb', '{"zh-TW":["通過；傳遞"],"en":["to go by","to hand over"]}', NULL, 'pass a test / pass along', '[{"en":"She passed the certification exam.","zh-TW":"她通過了認證考試。"},{"en":"Please pass this information along.","zh-TW":"請將這個消息轉達。"}]', '{"verb":"pass","noun":"pass","noun2":"passage","noun3":"passenger"}', NULL, 1, 2248, NULL),
(2249, 'passionate', '/ˈpæʃənət/', 'adjective', '{"zh-TW":["熱情的；熱烈的"],"en":["showing or caused by strong feelings"]}', '{"root":{"text":"passion","meaning":"suffer/feel (承受/感受)"},"suffix":{"text":"-ate","meaning":"having (具有)"},"logic":"具有強烈感受的，即「熱情的」。"}', 'passionate about / passionate speech', '[{"en":"He is passionate about environmental protection.","zh-TW":"他對環境保護充滿熱情。"},{"en":"She gave a passionate speech about equality.","zh-TW":"她發表了一場關於平等的激昂演說。"}]', '{"noun":"passion","adverb":"passionately"}', NULL, 4, 2249, NULL);
