(2257, 'patient', '/ˈpeɪʃənt/', 'adjective', '{"zh-TW":["有耐心的；病人","有耐心的"],"en":["able to wait calmly","a person receiving medical care","able to wait without becoming annoyed"]}', '{"root":{"text":"pati","meaning":"suffer/endure (承受)"},"suffix":{"text":"-ent","meaning":"being (…的)"},"logic":"能承受等待的，即「有耐心的」。"}', 'be patient / patient care; be patient / patient with', '[{"en":"Please be patient; we are working on it.","zh-TW":"請有耐心，我們正在處理中。"},{"en":"Patient satisfaction is our priority.","zh-TW":"病患滿意度是我們的首要任務。"},{"en":"Please be patient while we process your request.","zh-TW":"請耐心等候我們處理您的要求。"},{"en":"Good teachers are patient with students.","zh-TW":"好老師對學生有耐心。"}]', '{"adjective":"patient","noun":"patient","noun2":"patience","adjective2":"impatient","adverb":"patiently"}', NULL, 3, 2257, NULL),
(2258, 'patron', '/ˈpeɪtrən/', 'noun', '{"zh-TW":["顧客；贊助人"],"en":["a customer; a supporter"]}', '{"root":{"text":"patr","meaning":"father (父親)"}}', 'regular patron / patron of the arts', '[{"en":"The restaurant values its regular patrons.","zh-TW":"餐廳重視常客。"},{"en":"She is a well-known patron of the arts.","zh-TW":"她是知名的藝術贊助人。"}]', '{"noun":"patronage","verb":"patronize"}', NULL, 2, 2258, NULL),
