(2280, 'perform', '/pərˈfɔːrm/', 'verb', '{"zh-TW":["表演；執行","執行；履行","表現"],"en":["to carry out an action","to entertain an audience","to carry out a task","to function or do well"]}', '{"prefix":{"text":"per-","meaning":"through (通過)"},"root":{"text":"form","meaning":"provide (提供)"},"logic":"徹底提供（表演），即「表演」。"}', 'perform a task / perform on stage; perform a task / perform well / perform duties', '[{"en":"The band will perform live tonight.","zh-TW":"樂團今晚將現場表演。"},{"en":"She performed the surgery successfully.","zh-TW":"她成功地執行了手術。"},{"en":"The system performs well under pressure.","zh-TW":"系統在壓力下表現良好。"},{"en":"Employees must perform their duties efficiently.","zh-TW":"員工必須有效履行職責。"}]', '{"noun":"performance","noun2":"performer"}', NULL, 3, 2280, 172),
