(2282, 'performance-based', 'pərˈfɔːrməns beɪst', 'adjective', '{"zh-TW":["績效導向的；以績效為基礎的","按績效考核的"],"en":["based on measurable results","tied to output"]}', NULL, 'performance-based bonus/performance-based review', '[{"en":"Our compensation is performance-based.","zh-TW":"我們的薪酬是基於績效的。"}]', NULL, NULL, 5, 2282, NULL),
(2283, 'period', '/ˈpɪriəd/', 'noun', '{"zh-TW":["期間；時期"],"en":["a length of time"]}', '{"root":{"text":"peri","meaning":"around (周圍)"}}', 'during this period / trial period / period of time', '[{"en":"Sales declined during this period.","zh-TW":"這段期間銷售下降。"},{"en":"The trial period is 90 days.","zh-TW":"試用期為90天。"}]', '{"adjective":"periodic, periodical","adverb":"periodically"}', NULL, 2, 2283, NULL),
(2284, 'periodic', '/ˌpɪəriˈɒdɪk/', 'adjective', '{"zh-TW":["定期的；週期性的"],"en":["occurring or recurring at regular intervals"]}', NULL, 'periodic reports / periodic review / periodic maintenance', '[{"en":"Periodic maintenance prevents costly equipment breakdowns.","zh-TW":"定期維護防止代價高昂的設備故障。"},{"en":"The contract requires periodic performance reports every quarter.","zh-TW":"合約要求每季提交定期績效報告。"}]', '{"adverb":"periodically","noun":"period"}', NULL, 3, 2284, NULL),
(2285, 'perishable', '/ˈperɪʃəbəl/', 'adjective', '{"zh-TW":["易腐的；易損壞的"],"en":["liable to decay or spoil quickly, especially of food products"]}', NULL, 'perishable goods / perishable cargo / handle perishables', '[{"en":"Perishable goods require refrigerated transport.","zh-TW":"易腐商品需要冷藏運輸。"},{"en":"The perishable cargo was given priority handling at the airport.","zh-TW":"易腐貨物在機場獲得了優先處理。"}]', '{"noun":"perishables"}', NULL, 4, 2285, NULL),
(2286, 'permanent', '/ˈpɜːrmənənt/', 'adjective', '{"zh-TW":["永久的；長期的"],"en":["lasting forever or for a long time"]}', '{"prefix":{"text":"per-","meaning":"through"},"root":{"text":"man","meaning":"remain (留下)"},"suffix":{"text":"-ent","meaning":"...的"}}', 'permanent position / permanent damage / permanent residence', '[{"en":"She was offered a permanent position.","zh-TW":"她獲得了正式職位。"},{"en":"The damage may be permanent.","zh-TW":"損害可能是永久的。"}]', '{"adverb":"permanently","noun":"permanence"}', NULL, 3, 2286, 413),
(2287, 'permit', '/pərˈmɪt/', 'verb', '{"zh-TW":["允許；許可"],"en":["to give permission for something","to allow something"]}', '{"prefix":{"text":"per-","meaning":"through (通過)"},"root":{"text":"mit","meaning":"send (送)"},"logic":"讓其通過放行，即「允許」。"}', 'permit access / weather permitting / work permit; permit sb. to do / work permit / building permit', '[{"en":"Photography is not permitted inside the museum.","zh-TW":"博物館內不允許拍照。"},{"en":"The law does not permit this activity.","zh-TW":"法律不允許此活動。"},{"en":"Employees are not permitted to use personal phones.","zh-TW":"員工不允許使用個人手機。"},{"en":"You need a permit to park here.","zh-TW":"你需要許可證才能停這裡。"}]', '{"noun":"permit","noun2":"permission","adjective":"permissible"}', NULL, 2, 2287, 173),
(2288, 'persist', '/pərˈsɪst/', 'verb', '{"zh-TW":["堅持；持續"],"en":["to continue firmly; to last"]}', '{"prefix":{"text":"per-","meaning":"through"},"root":{"text":"sist","meaning":"stand (站立)"}}', 'persist in / persist with / if problems persist', '[{"en":"If the problem persists, contact support.","zh-TW":"如問題持續，請聯繫支援。"},{"en":"She persisted in her efforts despite setbacks.","zh-TW":"儘管受挫她仍堅持努力。"}]', '{"noun":"persistence","adjective":"persistent","adverb":"persistently"}', NULL, 3, 2288, NULL),
(2289, 'person', 'ˈpɜːrsən', 'noun', '{"zh-TW":["人；個人","當事人"],"en":["a human being","a specific individual"]}', NULL, 'contact person/key person', '[{"en":"She is the key person for this account.","zh-TW":"她是這個帳戶的關鍵人物。"}]', '{"adjective":"personal","adverb":"personally"}', NULL, 2, 2289, NULL),
(2290, 'personal', '/ˈpɜːrsənəl/', 'adjective', '{"zh-TW":["個人的；私人的"],"en":["relating to a particular person"]}', '{"root":{"text":"person","meaning":"person (人)"},"suffix":{"text":"-al","meaning":"...的"}}', 'personal information / personal opinion / personal belongings', '[{"en":"Do not share personal information online.","zh-TW":"不要在網上分享個人資訊。"},{"en":"This is my personal opinion.","zh-TW":"這是我個人意見。"}]', '{"noun":"personality","adverb":"personally","verb":"personalize"}', NULL, 3, 2290, NULL),
(2291, 'personnel', '/ˌpɜːrsəˈnɛl/', 'noun', '{"zh-TW":["人員；員工"],"en":["the people employed in an organization"]}', '{"root":{"text":"person","meaning":"person (人)"}}', 'personnel department / key personnel / military personnel', '[{"en":"All personnel must attend the training.","zh-TW":"所有人員必須參加培訓。"},{"en":"The personnel department handles hiring.","zh-TW":"人事部門處理招聘。"}]', NULL, NULL, 3, 2291, 44),
(2292, 'perspective', '/pərˈspektɪv/', 'noun', '{"zh-TW":["觀點；角度","觀點；視角"],"en":["a particular way of viewing things","a way of thinking about something"]}', '{"prefix":{"text":"per-","meaning":"through (透過)"},"root":{"text":"spect","meaning":"look (看)"},"suffix":{"text":"-ive","meaning":"relating to (相關的)"},"logic":"透過某角度來看，即「觀點」。"}', 'from my perspective / gain perspective / new perspective; from a different perspective / put into perspective / gain perspective; from my perspective / gain a new perspective / put in perspective', '[{"en":"From my perspective, the plan makes sense.","zh-TW":"從我的角度來看，這個計畫合理。"},{"en":"Travel gives you a new perspective on life.","zh-TW":"旅行給你新的人生觀點。"},{"en":"Try to see it from the customer''s perspective.","zh-TW":"試從客戶角度看。"},{"en":"The report puts the data into perspective.","zh-TW":"報告讓數據更有脈絡。"},{"en":"From a financial perspective, the deal is good.","zh-TW":"從財務角度看，這筆交易不錯。"},{"en":"Travel helps you gain new perspectives.","zh-TW":"旅行幫助你獲得新的觀點。"}]', NULL, NULL, 4, 2292, 414),
(2293, 'persuade', '/pərˈsweɪd/', 'verb', '{"zh-TW":["說服"],"en":["to cause someone to do or believe something"]}', '{"prefix":{"text":"per-","meaning":"thoroughly"},"root":{"text":"suade","meaning":"advise (勸)"}}', 'persuade sb. to do / be persuaded', '[{"en":"She persuaded the board to approve the budget.","zh-TW":"她說服董事會批准預算。"},{"en":"I was persuaded by his argument.","zh-TW":"我被他的論點說服了。"}]', '{"noun":"persuasion","adjective":"persuasive","adverb":"persuasively"}', NULL, 3, 2293, NULL),
(2294, 'pessimistic', '/ˌpesɪˈmɪstɪk/', 'adjective', '{"zh-TW":["悲觀的"],"en":["tending to see the worst aspect of things"]}', '{"root":{"text":"pessim","meaning":"worst (最壞)"},"suffix":{"text":"-istic","meaning":"characterized by (以…為特徵)"},"logic":"以看到最壞面為特徵的，即「悲觀的」。"}', 'pessimistic view / pessimistic about', '[{"en":"He has a pessimistic view of the economy.","zh-TW":"他對經濟持悲觀看法。"},{"en":"Don''t be so pessimistic about everything.","zh-TW":"不要對所有事都那麼悲觀。"}]', '{"noun":"pessimism","noun2":"pessimist"}', NULL, 4, 2294, NULL),
(2295, 'petition', '/pɪˈtɪʃən/', 'noun', '{"zh-TW":["請願書","請願書；申請"],"en":["a formal written request signed by many people","a formal written request"]}', '{"root":{"text":"petit","meaning":"seek (尋求)"},"suffix":{"text":"-ion","meaning":"名詞後綴"}}', 'sign a petition / online petition; file a petition / sign a petition', '[{"en":"Over 10,000 people signed the petition.","zh-TW":"超過一萬人簽署了請願書。"},{"en":"They started an online petition.","zh-TW":"他們發起了一份線上請願書。"},{"en":"Employees signed a petition for better conditions.","zh-TW":"員工簽署了改善條件的請願書。"},{"en":"She filed a petition with the court.","zh-TW":"她向法院提交了申請。"}]', '{"verb":"petition","noun":"petitioner"}', NULL, 3, 2295, NULL),
(2296, 'pharmaceutical', '/ˌfɑːrməˈsuːtɪkəl/', 'adjective', '{"zh-TW":["製藥的；藥物的"],"en":["relating to the preparation and dispensing of drugs"]}', NULL, 'pharmaceutical company / pharmaceutical product', '[{"en":"The pharmaceutical company launched a new drug this year.","zh-TW":"製藥公司今年推出了一種新藥。"},{"en":"Pharmaceutical research requires years of clinical trials.","zh-TW":"製藥研究需要多年的臨床試驗。"}]', '{"noun":"pharmacist","noun2":"pharmacy"}', NULL, 5, 2296, NULL),
(2297, 'pharmacy', '/ˈfɑːrməsi/', 'noun', '{"zh-TW":["藥局；藥房"],"en":["a shop where medicines are dispensed and sold"]}', NULL, 'local pharmacy / hospital pharmacy', '[{"en":"Pick up your prescription at the pharmacy.","zh-TW":"在藥局領取您的處方藥。"},{"en":"The pharmacy is open until 10 pm.","zh-TW":"藥局開到晚上10點。"}]', '{"noun":"pharmacist","adjective":"pharmaceutical"}', NULL, 3, 2297, NULL),
(2298, 'phase', '/feɪz/', 'noun', '{"zh-TW":["階段；時期"],"en":["a distinct stage in a process"]}', NULL, 'first phase / phase out / phase in / implementation phase', '[{"en":"The project is now in its final phase.","zh-TW":"項目現在處於最後階段。"},{"en":"We will phase out the old system gradually.","zh-TW":"我們將逐步淘汰舊系統。"}]', '{"verb":"phase"}', NULL, 2, 2298, 174),
(2299, 'phenomenon', '/fɪˈnɒmɪnən/', 'noun', '{"zh-TW":["現象"],"en":["a fact or situation that is observed"]}', '{"root":{"text":"pheno","meaning":"appear (出現)"}}', 'natural phenomenon / social phenomenon', '[{"en":"This is a common phenomenon in the industry.","zh-TW":"這是行業中的常見現象。"},{"en":"Remote work has become a global phenomenon.","zh-TW":"遠程工作已成為全球現象。"}]', '{"adjective":"phenomenal","adverb":"phenomenally"}', NULL, 4, 2299, NULL);
