(2302, 'pick', '/pɪk/', 'verb', '{"zh-TW":["挑選；撿起"],"en":["to choose","to take up with fingers"]}', NULL, 'pick up / hand-picked', '[{"en":"I will pick you up at the airport.","zh-TW":"我去機場接你。"},{"en":"She was hand-picked for the role.","zh-TW":"她是被精心挑選擔任這個職位的。"}]', '{"verb":"pick","noun":"pick","adjective":"picky"}', NULL, 1, 2302, NULL),
(2303, 'picture', '/ˈpɪktʃər/', 'noun', '{"zh-TW":["圖片；情況"],"en":["a visual image","a situation or description"]}', NULL, 'big picture / get the picture', '[{"en":"Let''s focus on the big picture.","zh-TW":"讓我們關注大局。"},{"en":"Do you get the picture?","zh-TW":"你了解情況了嗎？"}]', '{"noun":"picture","verb":"picture"}', NULL, 3, 2303, NULL),
