(2305, 'pioneer', '/ˌpaɪəˈnɪr/', 'noun', '{"zh-TW":["先驅；開拓者"],"en":["a person who is among the first to do something"]}', NULL, 'pioneer in the field / pioneer of technology', '[{"en":"She was a pioneer in the field of AI.","zh-TW":"她是AI領域的先驅。"},{"en":"The company pioneered online shopping.","zh-TW":"該公司開創了線上購物。"}]', '{"verb":"pioneer","adjective":"pioneering"}', NULL, 3, 2305, 706),
(2306, 'pipeline', '/ˈpaɪplaɪn/', 'noun', '{"zh-TW":["銷售管道；流水線"],"en":["the set of potential deals in various stages of the sales process"]}', NULL, 'sales pipeline / build the pipeline / pipeline management / pipeline review', '[{"en":"The sales team has a healthy pipeline of $5 million in deals.","zh-TW":"銷售團隊擁有價值500萬美元的健康銷售管道。"},{"en":"Pipeline reviews help forecast future revenue accurately.","zh-TW":"管道審查幫助準確預測未來收入。"}]', NULL, NULL, 3, 2306, 905),
(2307, 'pitch', '/pɪtʃ/', 'noun', '{"zh-TW":["推銷；提案"],"en":["a presentation aimed at persuading someone to buy or invest"]}', NULL, 'sales pitch / pitch to investors', '[{"en":"His sales pitch convinced the client to sign the contract.","zh-TW":"他的推銷說服了客戶簽署合約。"},{"en":"The startup made a compelling pitch to venture capitalists.","zh-TW":"初創公司向風險資本家做了引人注目的提案。"}]', '{"verb":"pitch","adjective":"pitched"}', NULL, 2, 2307, NULL),
(2308, 'pivot', '/ˈpɪvət/', 'verb', '{"zh-TW":["轉向；業務轉型"],"en":["to change a company''s strategy or business model significantly"]}', NULL, 'pivot the business / startup pivot / strategic pivot', '[{"en":"The startup pivoted from B2C to B2B after market research.","zh-TW":"新創公司在市場研究後從B2C轉向B2B。"},{"en":"Pivoting to digital services saved the company during the crisis.","zh-TW":"轉向數位服務在危機期間救了公司。"}]', '{"noun":"pivot","adjective":"pivotal"}', NULL, 2, 2308, NULL),
(2309, 'pivotal', '/ˈpɪvɪtəl/', 'adjective', '{"zh-TW":["關鍵的；核心的"],"en":["of crucial importance in relation to the development or success of something"]}', NULL, 'pivotal role / pivotal moment / pivotal decision', '[{"en":"The CEO played a pivotal role in turning the company around.","zh-TW":"執行長在公司轉型中發揮了關鍵作用。"},{"en":"This is a pivotal moment for the organization''s future direction.","zh-TW":"這是組織未來方向的關鍵時刻。"}]', '{"adverb":"pivotally","noun":"pivot"}', NULL, 3, 2309, NULL),
(2310, 'place', '/pleɪs/', 'noun', '{"zh-TW":["地方；位置"],"en":["a particular area or position"]}', NULL, 'in place / take place', '[{"en":"The meeting will take place on Monday.","zh-TW":"會議將在週一舉行。"},{"en":"New policies are now in place.","zh-TW":"新政策現已到位。"}]', '{"noun":"place","verb":"place","noun2":"placement"}', NULL, 2, 2310, 175),
(2311, 'placement', '/ˈpleɪsmənt/', 'noun', '{"zh-TW":["實習安置；分班"],"en":["the process of placing students in jobs or classes"]}', NULL, 'job placement / placement test', '[{"en":"The university has an excellent job placement record.","zh-TW":"這所大學有出色的就業安置記錄。"},{"en":"A placement test determines which course level suits you.","zh-TW":"分班測試確定哪個課程級別適合您。"}]', '{"verb":"place","adjective":"placed"}', NULL, 3, 2311, 906),
(2312, 'plagiarism', '/ˈpleɪdʒərɪzəm/', 'noun', '{"zh-TW":["抄襲；剽竊"],"en":["taking someone else''s work and presenting it as your own","using someone''s work as your own without credit"]}', NULL, 'avoid plagiarism / plagiarism check', '[{"en":"The company has strict policies against plagiarism.","zh-TW":"公司有嚴格的反抄襲政策。"},{"en":"All content goes through a plagiarism check.","zh-TW":"所有內容都要經過抄襲檢查。"},{"en":"Plagiarism is a serious offense.","zh-TW":"抄襲是嚴重的違規行為。"},{"en":"The software detects plagiarism.","zh-TW":"這軟體能偵測抄襲。"}]', '{"noun":"plagiarism","verb":"plagiarize","noun2":"plagiarist"}', NULL, 4, 2312, NULL),
(2313, 'plaintiff', '/ˈpleɪntɪf/', 'noun', '{"zh-TW":["原告"],"en":["the person who brings a case to court"]}', NULL, 'the plaintiff argued / plaintiff''s attorney', '[{"en":"The plaintiff filed the lawsuit.","zh-TW":"原告提起了訴訟。"},{"en":"The plaintiff''s claims were dismissed.","zh-TW":"原告的訴求被駁回了。"}]', NULL, NULL, 3, 2313, NULL),
(2314, 'plan', '/plæn/', 'noun', '{"zh-TW":["計畫"],"en":["a detailed proposal for doing something"]}', NULL, 'action plan / plan ahead', '[{"en":"We need a clear action plan.","zh-TW":"我們需要一個明確的行動計畫。"},{"en":"Always plan ahead for busy periods.","zh-TW":"永遠要提前規劃忙碌時期。"}]', '{"noun":"plan","verb":"plan","noun2":"planner","noun3":"planning"}', NULL, 1, 2314, 176),
(2315, 'planning', 'ˈplænɪŋ', 'noun', '{"zh-TW":["規劃；計畫","策劃"],"en":["the process of making plans","organizing for the future"]}', NULL, 'strategic planning/advance planning', '[{"en":"Good planning prevents project failures.","zh-TW":"良好的規劃可以防止專案失敗。"}]', '{"verb":"plan","adjective":"planned"}', NULL, 3, 2315, 605),
(2316, 'plant', '/plɑːnt/', 'noun, verb', '{"zh-TW":["【主要意義-名詞】植物；工廠；設備","【次要意義-動詞】安插；秘密放置（某物/某人）","【次要意義-動詞】安置；建立（機構）"],"en":["[primary - noun] a living organism; a factory or industrial facility","[secondary - verb] to place secretly or covertly in a location","[secondary - verb] to establish an idea or organization in a place"]}', NULL, 'manufacturing plant / power plant / plant evidence / plant an idea', '[{"en":"The new manufacturing plant will create over 500 jobs.","zh-TW":"新的製造工廠將創造逾500個工作崗位。"},{"en":"Investigators suspected that the evidence had been planted.","zh-TW":"調查人員懷疑證據是被人為安插的。"},{"en":"The company plans to plant its first overseas subsidiary in Singapore.","zh-TW":"公司計劃在新加坡建立第一個海外子公司。"}]', '{"noun":"plantation","adjective":"planted"}', 'plant 作名詞指「工廠/設備」（manufacturing plant），動詞 plant = 「秘密安置/安插」，這些次要意義在 TOEIC 工業或調查報導類文章中出現，容易與「種植」混淆。', 2, 2316, NULL),
(2317, 'platform', '/ˈplætfɔːrm/', 'noun', '{"zh-TW":["平台"],"en":["a system for running applications"]}', NULL, 'social media platform / online platform', '[{"en":"Which platform do you use?","zh-TW":"你用哪個平台？"},{"en":"The company launched a new platform.","zh-TW":"公司推出了一個新平台。"}]', NULL, NULL, 3, 2317, NULL),
(2318, 'play', '/pleɪ/', 'verb', '{"zh-TW":["扮演；玩"],"en":["to take part in a game","to perform a role"]}', NULL, 'play a role / fair play', '[{"en":"Technology plays a key role in our strategy.","zh-TW":"科技在我們的策略中扮演關鍵角色。"},{"en":"We believe in fair play.","zh-TW":"我們相信公平競爭。"}]', '{"verb":"play","noun":"play","noun2":"player"}', NULL, 1, 2318, NULL),
(2319, 'pledge', '/plɛdʒ/', 'verb', '{"zh-TW":["承諾；保證"],"en":["to make a formal promise"]}', NULL, 'pledge support / pledge to do sth.', '[{"en":"The CEO pledged to reduce emissions.","zh-TW":"執行長承諾減少排放。"},{"en":"They pledged their full support.","zh-TW":"他們承諾全力支持。"}]', '{"noun":"pledge"}', NULL, 2, 2319, NULL),
(2320, 'plunge', '/plʌndʒ/', 'verb', '{"zh-TW":["暴跌；驟降"],"en":["to fall or drop suddenly"]}', NULL, 'plunge into / stock prices plunged / take the plunge', '[{"en":"Stock prices plunged after the announcement.","zh-TW":"公告後股價暴跌。"},{"en":"She decided to take the plunge and start her own business.","zh-TW":"她決定冒險創業。"}]', '{"noun":"plunge"}', NULL, 2, 2320, NULL),
(2321, 'podium', '/ˈpəʊdiəm/', 'noun', '{"zh-TW":["講台；演講台"],"en":["a raised platform from which a speaker addresses an audience"]}', NULL, 'stand at the podium / address from the podium', '[{"en":"She confidently took the podium to deliver her speech.","zh-TW":"她自信地走上講台發表演講。"},{"en":"The presenter stood at the podium throughout the keynote.","zh-TW":"演講者在主題演講期間一直站在講台上。"}]', NULL, NULL, 2, 2321, NULL),
(2322, 'point', '/pɔɪnt/', 'noun', '{"zh-TW":["要點；觀點","分數"],"en":["a key idea","a unit of scoring"]}', NULL, 'make a point / point out / turning point / to the point', '[{"en":"She made an excellent point in the meeting.","zh-TW":"她在會議上提出了很好的觀點。"},{"en":"I''d like to point out a few issues.","zh-TW":"我想指出幾個問題。"}]', '{"verb":"point","adjective":"pointed"}', NULL, 2, 2322, NULL),
(2323, 'policy', '/ˈpɒlɪsi/', 'noun', '{"zh-TW":["政策；方針"],"en":["a plan of action adopted by an organization"]}', '{"root":{"text":"poli","meaning":"city, state (國家)"}}', 'company policy / insurance policy / implement a policy', '[{"en":"The new policy takes effect next month.","zh-TW":"新政策下月生效。"},{"en":"It is against company policy to accept gifts.","zh-TW":"接受禮物違反公司政策。"}]', '{"noun":"policyholder"}', NULL, 2, 2323, 45),
(2324, 'policyholder', '/ˈpɒlɪsiˌhoʊldər/', 'noun', '{"zh-TW":["保單持有人；被保險人"],"en":["a person or organization that holds an insurance policy"]}', NULL, 'rights of the policyholder / policyholder claims', '[{"en":"The policyholder must notify the insurer within 48 hours of an incident.","zh-TW":"保單持有人必須在事故發生後48小時內通知保險公司。"},{"en":"All policyholders received a notice about the rate increase.","zh-TW":"所有保單持有人都收到了費率上調的通知。"}]', NULL, NULL, 4, 2324, NULL),
