(2327, 'pool', '/puːl/', 'noun', '{"zh-TW":["資源池；共用資金"],"en":["a shared supply of resources"]}', NULL, 'pool resources / talent pool / car pool', '[{"en":"We need to pool our resources for this project.","zh-TW":"我們需要集中資源做這項目。"},{"en":"The company maintains a talent pool.","zh-TW":"公司維護人才庫。"}]', '{"verb":"pool"}', NULL, 1, 2327, NULL),
