(2331, 'port', '/pɔːrt/', 'noun', '{"zh-TW":["港口"],"en":["a town or city with a harbor for ships"]}', NULL, 'cruise port / home port', '[{"en":"The cruise docks at the port of Barcelona.","zh-TW":"郵輪停靠在巴塞隆納港。"},{"en":"The port handles millions of passengers each year.","zh-TW":"該港口每年接待數百萬名乘客。"}]', NULL, NULL, 1, 2331, NULL),
