(2333, 'portfolio', '/pɔːrtˈfoʊlioʊ/', 'noun', '{"zh-TW":["投資組合；作品集"],"en":["a collection of investments or projects held by an entity"]}', NULL, 'investment portfolio / diversified portfolio / portfolio management', '[{"en":"He balanced his portfolio between stocks and bonds.","zh-TW":"他在股票和債券之間平衡了自己的投資組合。"},{"en":"The portfolio returned 12% over the past year.","zh-TW":"投資組合過去一年回報率為12%。"}]', '{"plural":"portfolios"}', NULL, 3, 2333, NULL),
