(2336, 'pose', '/poʊz/', 'verb', '{"zh-TW":["構成；提出"],"en":["to present or constitute"]}', NULL, 'pose a threat / pose a question / pose a challenge', '[{"en":"This poses a serious threat to the business.","zh-TW":"這對業務構成嚴重威脅。"},{"en":"The new regulation poses challenges.","zh-TW":"新規定帶來挑戰。"}]', NULL, NULL, 1, 2336, NULL),
(2337, 'position', '/pəˈzɪʃən/', 'noun', '{"zh-TW":["職位","位置","立場"],"en":["a job","a place","an opinion"]}', '{"root":{"text":"posit","meaning":"place (放置)"},"suffix":{"text":"-ion","meaning":"名詞後綴"}}', 'apply for a position / market position / bargaining position', '[{"en":"She applied for the managerial position.","zh-TW":"她申請了管理職位。"},{"en":"The company holds a strong market position.","zh-TW":"公司擁有強勁的市場地位。"}]', '{"verb":"position"}', NULL, 3, 2337, 46),
(2338, 'positioning', '/pəˈzɪʃənɪŋ/', 'noun', '{"zh-TW":["市場定位"],"en":["the process of creating a specific image in consumers'' minds"]}', NULL, 'brand positioning / market positioning / positioning strategy', '[{"en":"The company''s positioning as a premium brand justifies higher prices.","zh-TW":"公司作為高端品牌的定位是較高定價的依據。"},{"en":"Positioning the product for young professionals drove strong sales.","zh-TW":"將產品定位於年輕專業人士推動了強勁銷售。"}]', '{"verb":"position","adjective":"positioned"}', NULL, 4, 2338, NULL),
(2339, 'positive', '/ˈpɒzɪtɪv/', 'adjective', '{"zh-TW":["積極的；正面的","肯定的","積極的","確定的"],"en":["good; constructive","certain; sure","certain"]}', '{"root":{"text":"posit","meaning":"place (放置)"},"suffix":{"text":"-ive","meaning":"...的"}}', 'positive feedback / positive impact / positive attitude; positive feedback / positive impact / test positive', '[{"en":"The feedback has been overwhelmingly positive.","zh-TW":"反饋非常正面。"},{"en":"A positive attitude makes a difference.","zh-TW":"積極態度會帶來改變。"},{"en":"A positive attitude makes a difference.","zh-TW":"積極的態度會帶來改變。"}]', '{"adverb":"positively","noun":"positivity"}', NULL, 3, 2339, NULL),
