(2342, 'post', '/poʊst/', 'verb', '{"zh-TW":["【主要意義-動詞/名詞】張貼；郵件","【次要意義-名詞】職位；職務；崗位","【次要意義-動詞】派駐；調派（到某地任職）","【次要意義-名詞】（軍隊）駐地；哨位"],"en":["[primary] to mail something; a letter or package","[secondary - noun] a job or position in an organization","[secondary - verb] to send someone to work in a particular place","[secondary - noun] a military station"]}', NULL, 'fill a post / apply for a post / post someone abroad / keep someone posted', '[{"en":"We are looking for candidates to fill the post of regional manager.","zh-TW":"我們正在尋找候選人填補地區經理的職位。"},{"en":"She was posted to the Tokyo office for a two-year assignment.","zh-TW":"她被派駐東京辦事處，執行為期兩年的任務。"},{"en":"Please keep me posted on any developments in the negotiation.","zh-TW":"請隨時讓我了解談判的最新進展。"}]', '{"noun":"posting"}', 'post = 「職位」（fill a post）和「派駐」（post someone to）是 TOEIC 人事管理文章的高頻用法，keep someone posted（隨時通知）也是常考片語。', 1, 2342, NULL),
(2343, 'post-mortem', '/ˈpoʊst ˈmɔːrtəm/', 'noun', '{"zh-TW":["事後檢討；復盤"],"en":["a review conducted after a project or incident to identify lessons"]}', NULL, 'conduct a post-mortem / post-mortem report / post-mortem analysis', '[{"en":"The post-mortem identified communication failures as a root cause.","zh-TW":"事後檢討將溝通失敗確定為根本原因。"},{"en":"Regular post-mortems help teams continuously improve their processes.","zh-TW":"定期復盤幫助團隊持續改進其流程。"}]', NULL, NULL, 4, 2343, NULL),
(2344, 'postgraduate', '/ˌpəʊstˈɡrædʒuɪt/', 'adjective', '{"zh-TW":["研究所的；研究生的"],"en":["relating to study done after a first degree"]}', NULL, 'postgraduate degree / postgraduate program', '[{"en":"She enrolled in a postgraduate program in public health.","zh-TW":"她報名了公共衛生研究所課程。"},{"en":"Postgraduate study often leads to specialized career opportunities.","zh-TW":"研究所學習往往帶來專業的職業機會。"}]', '{"noun":"postgraduate"}', NULL, 4, 2344, NULL),
