(2346, 'postpone', '/poʊstˈpoʊn/', 'verb', '{"zh-TW":["延期；推遲"],"en":["to arrange for later than planned"]}', '{"prefix":{"text":"post-","meaning":"after (之後)"},"root":{"text":"pone","meaning":"put (放)"}}', 'postpone a meeting / postpone indefinitely', '[{"en":"The meeting has been postponed until Friday.","zh-TW":"會議已推遲到週五。"},{"en":"They decided to postpone the product launch.","zh-TW":"他們決定推遲產品發布。"}]', '{"noun":"postponement"}', NULL, 3, 2346, 707),
(2347, 'potential', '/pəˈtenʃl/', 'noun', '{"zh-TW":["潛力；可能性","潛在的；可能的"],"en":["latent qualities that may be developed","possible; capable of becoming"]}', '{"root":{"text":"potent","meaning":"power (力量)"},"suffix":{"text":"-ial","meaning":"relating to (相關的)"},"logic":"與潛在力量相關的，即「潛力」。"}', 'reach one''s potential / growth potential / potential risk; potential risk / potential customer / growth potential', '[{"en":"She has the potential to become a great leader.","zh-TW":"她有潛力成為偉大的領導者。"},{"en":"We must consider the potential risks.","zh-TW":"我們必須考慮潛在風險。"},{"en":"There are potential risks in this investment.","zh-TW":"這項投資有潛在風險。"},{"en":"The market has great growth potential.","zh-TW":"市場有很大的成長潛力。"}]', '{"adjective":"potential","adverb":"potentially","noun":"potential, potentiality"}', NULL, 3, 2347, 415),
